update public.official_exam_questions
set review_note = 'Item CERTO. O enunciado apresenta um balancete completo e pede apenas o julgamento do item, no formato CEBRASPE: C = Certo e E = Errado. Não se trata de uma questão de múltipla escolha com alternativas A–E. Para calcular o Ativo, some somente as contas que representam bens, direitos ou despesas antecipadas: Bancos R$ 95.000 + Materiais de consumo R$ 4.000 + Máquinas R$ 9.000 + Despesa antecipada R$ 1.200 = R$ 109.200. Contas a pagar é Passivo; capital pertence ao Patrimônio Líquido; receita e despesas são contas de resultado e não entram diretamente no total do Ativo. Portanto, o item está CERTO. Dica: em um balancete, classifique cada conta antes de somar. Ativo = bens, direitos e despesas antecipadas; Passivo = obrigações; PL = capital e resultados acumulados; receitas e despesas formam o resultado do período. | Explicação didática revisada.'
where id = '70141ce9-3c8f-41ca-8f5b-12a0d09d8189';
